export const concepts = [
  ['JSIN-R2-CON001', 'source file and runtime', 'A .js file stores instructions; Node.js is the program that reads and executes them.', '`node hello.js` runs the saved file named hello.js.', 'Assuming VS Code executes a file merely because it is open.'],
  ['JSIN-R2-CON002', 'REPL', 'A temporary read-evaluate-print loop for trying small expressions one at a time.', 'Start `node`, enter `2 + 3`, then leave with `.exit`.', 'Treating REPL history as a saved repeatable program.'],
  ['JSIN-R2-CON003', 'error location', 'The file, line, and marker in an error narrow where the runtime first noticed a problem.', 'A missing quote may be reported on the line where the string began.', 'Changing several unrelated lines before reading the first error.'],
  ['JSIN-R2-CON004', 'const and let', 'const prevents rebinding; let permits intentional reassignment.', '`const taxRate = 0.075`; `let total = 0`.', 'Assuming const makes an object or array deeply immutable.'],
  ['JSIN-R2-CON005', 'value type', 'A type describes how JavaScript represents and operates on a value.', '`typeof 42` is `"number"`; `typeof "42"` is `"string"`.', 'Expecting numeric-looking text to behave exactly like a number.'],
  ['JSIN-R2-CON006', 'explicit conversion', 'Conversion deliberately produces a value of another type before it is used.', '`Number("12")` produces the number 12.', 'Adding unconverted text and receiving concatenation.'],
  ['JSIN-R2-CON007', 'template literal', 'A backtick string can insert an expression with ${...}.', '``Remaining: ${remaining}`` includes the calculated value.', 'Using ordinary quotes and expecting ${...} to be evaluated.'],
  ['JSIN-R2-CON008', 'strict equality', '=== compares value and type without converting either operand.', '`5 === "5"` is false.', 'Using == when a type mismatch should be visible.'],
  ['JSIN-R2-CON009', 'Boolean expression', 'An expression whose result is true or false and can control a decision.', '`age >= 16 && hasTicket`.', 'Comparing a Boolean to the string `"true"`.'],
  ['JSIN-R2-CON010', 'conditional branch', 'if/else selects a path according to Boolean conditions in order.', 'Reject invalid input before checking ticket rules.', 'Putting a broad branch before a more specific validation branch.'],
  ['JSIN-R2-CON011', 'finite-number guard', 'Number.isFinite confirms that a converted value is a usable finite number.', '`Number.isFinite(Number(ageText))` rejects `"unknown"`.', 'Using truthiness, which also rejects valid zero.'],
  ['JSIN-R2-CON012', 'array index and length', 'Array indexes begin at zero while length counts stored elements.', 'The last item is `items[items.length - 1]`.', 'Reading `items[items.length]` and expecting the last item.'],
  ['JSIN-R2-CON013', 'array update', 'Methods such as push and pop change the ordered collection.', '`scores.push(74)` appends a score.', 'Using indexOf as though it returns the matching value.'],
  ['JSIN-R2-CON014', 'loop boundary', 'A loop condition decides exactly which indexes or values are processed.', '`index < scores.length` stays inside valid indexes.', 'Using <= length and processing one nonexistent entry.'],
  ['JSIN-R2-CON015', 'accumulator', 'A variable updated during iteration holds a running result.', '`total += score` builds the sum.', 'Resetting the accumulator inside the loop body.'],
  ['JSIN-R2-CON016', 'function contract', 'A focused function accepts stated inputs and produces one understandable result or effect.', '`calculateSubtotal(prices)` returns one subtotal.', 'Writing one function that reads, calculates, formats, saves, and prints everything.'],
  ['JSIN-R2-CON017', 'parameter and argument', 'A parameter names an input in the definition; an argument supplies a value at a call.', '`function greet(name)` and `greet("Ayo")`.', 'Assuming a parameter already contains a value before the function is called.'],
  ['JSIN-R2-CON018', 'return value', 'return sends a value back to the caller and ends that function call.', '`return subtotal * 0.9` lets the caller format the result.', 'Printing a value inside a helper when another function needs to use it.'],
  ['JSIN-R2-CON019', 'scope', 'A binding is available only in the region where it was declared and nested regions.', 'A const inside a function is local to that function.', 'Reading a local binding from outside its function.'],
  ['JSIN-R2-CON020', 'object property', 'An object groups named values that describe one record.', '`book.title` reads the title property.', 'Using an array index when the data is identified by a property name.'],
  ['JSIN-R2-CON021', 'class and instance', 'A class describes construction and shared methods; an instance holds one record’s data.', '`new Book("Kindred")` creates one Book instance.', 'Calling a class constructor without new.'],
  ['JSIN-R2-CON022', 'JSON round trip', 'Stringify converts supported data to JSON text; parse reconstructs data values from valid JSON text.', '`JSON.parse(JSON.stringify(records))` returns plain data.', 'Expecting parsed JSON to restore custom class methods.'],
  ['JSIN-R2-CON023', 'ECMAScript module', 'A module exposes selected bindings with export and consumes them with import.', '`export { addItem }` and `import { addItem } from "./items.js"`.', 'Importing a name that the other file did not export.'],
  ['JSIN-R2-CON024', 'defensive persistence', 'A program distinguishes absent storage from malformed existing storage before writing.', 'Create an empty list for a missing file, but stop on invalid JSON.', 'Overwriting a malformed file with an empty array and destroying evidence.'],
  ['JSIN-R2-CON025', 'automated assertion', 'An assertion compares actual behavior with an expected result and reports a mismatch.', '`assert.deepStrictEqual(actual, expected)` checks structured data.', 'Changing the expected result merely to make a failing test green.'],
  ['JSIN-R2-CON026', 'debugger step', 'A breakpoint and step command reveal values and control flow at a chosen line.', 'Pause before a return and inspect the local result.', 'Adding many console logs without first narrowing the failing case.'],
  ['JSIN-R2-CON027', 'command dispatch', 'A command-line program separates the requested action from its remaining argument values.', '`const args = process.argv.slice(2); const command = args[0];`.', 'Treating the Node executable and script path as learner commands.'],
  ['JSIN-R2-CON028', 'reproducible repository', 'A repository is reviewable when its committed files and README let another person run and test it safely.', 'README lists `node src/cli.js help` and `node --test`.', 'Publishing secrets, generated clutter, or undocumented commands.'],
].map(([id, term, simpleMeaning, example, commonMistake]) => ({ id, term, simpleMeaning, example, commonMistake }));

const build = ({
  week, title, outcome, brief, competencyIds, priorKnowledgeCompetencyIds, conceptRefs, whyItMatters,
  steps, criteria, hints, templates, stretch, sessions, finishedResult,
}) => {
  const prefix = `JSIN-R2-B-W${String(week).padStart(2, '0')}-01`;
  return {
    id: prefix,
    title,
    required: true,
    outcome,
    competencyIds,
    estimatedMinutes: sessions.reduce((sum, session) => sum + session.minutes, 0),
    brief,
    steps: steps.map((text, index) => ({ id: `${prefix}-S${String(index + 1).padStart(2, '0')}`, text })),
    acceptanceCriteria: criteria.map((text, index) => ({ id: `${prefix}-A${String(index + 1).padStart(2, '0')}`, text })),
    hints,
    templates: templates.map((item, index) => ({ id: `${prefix}-T${String(index + 1).padStart(2, '0')}`, ...item })),
    stretch,
    learnerGuide: {
      summary: brief,
      whyItMatters,
      priorKnowledgeCompetencyIds,
      finishedResult,
      conceptRefs,
      sessions: sessions.map((session, index) => ({
        id: `${prefix}-SESSION-${String(index + 1).padStart(2, '0')}`,
        title: session.title,
        estimatedMinutes: session.minutes,
        stepIds: session.stepIndexes.map((stepIndex) => `${prefix}-S${String(stepIndex).padStart(2, '0')}`),
      })),
    },
  };
};

